import { guardFirstWordIntegrity, validateDevanagariClueIntegrity } from './marathiClueSanitizer';
export { guardFirstWordIntegrity, validateDevanagariClueIntegrity };

const devanagariNonWord = '[^\\u0900-\\u097F\\u200C\\u200D]';

export function cleanClue(word: string, clue: string): string {
    const cleanWord = (word || '').trim();
    if (!clue || !cleanWord || cleanWord.length < 2) return clue;

    let cleaned = clue.trim();
    const escaped = cleanWord.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

    // 1. Remove bracketed / quoted word safely without stripping clue text
    cleaned = cleaned.replace(new RegExp(`\\[\\s*${escaped}\\s*\\]`, 'gi'), '');
    cleaned = cleaned.replace(new RegExp(`\\(\\s*${escaped}\\s*\\)`, 'gi'), '');
    cleaned = cleaned.replace(new RegExp(`['"‘“]${escaped}['"’”]?`, 'gi'), '');

    // 2. Replace standalone phrases with full word boundary
    cleaned = cleaned.replace(new RegExp(`(वापरली जाणारी|वापरला जाणारा|वापरले जाणारे)\\s+${escaped}(?=${devanagariNonWord}|$)`, 'g'), '$1 वस्तू / साधन');
    cleaned = cleaned.replace(new RegExp(`(खाल्ली जाणारी|खाल्ला जाणारा)\\s+${escaped}(?=${devanagariNonWord}|$)`, 'g'), '$1 चवदार सामग्री');
    cleaned = cleaned.replace(new RegExp(`(मिळणारी|मिळणारा)\\s+${escaped}(?=${devanagariNonWord}|$)`, 'g'), '$1 गोष्ट');

    // 3. Remove standalone word at the very end of the clue
    cleaned = cleaned.replace(new RegExp(`\\s+${escaped}\\s*$`, 'g'), '');
    cleaned = cleaned.replace(new RegExp(`\\s+${escaped}([।,;\\.\\s]+)$`, 'g'), '$1');

    // 4. If whole standalone word is still present, replace only whole word tokens naturally or use dictionary clue
    const wholeWordRegex = new RegExp(`(^|${devanagariNonWord})${escaped}(?=${devanagariNonWord}|$)`, 'g');
    if (wholeWordRegex.test(cleaned)) {
        if (MARATHI_DICTIONARY[cleanWord] && !MARATHI_DICTIONARY[cleanWord].includes(cleanWord)) {
            return MARATHI_DICTIONARY[cleanWord];
        }
        cleaned = cleaned.replace(wholeWordRegex, '$1ही गोष्ट');
    }

    // Clean formatting and strip dangling connectors without truncating legitimate Marathi words
    cleaned = cleaned.replace(/\s{2,}/g, ' ').trim();
    cleaned = cleaned.replace(/\s+(?:वा|किंवा|अथवा|आणि)\s*$/gi, '');
    cleaned = cleaned.replace(/^[:;\-–=,\s]+/, '').replace(/[:;\-–=,\s]+$/, '').trim();

    // Guard first word against any accidental truncation
    cleaned = guardFirstWordIntegrity(cleanWord, clue, cleaned);

    return cleaned || (MARATHI_DICTIONARY[cleanWord] || SMART_WORD_CLUES[cleanWord] || '');
}

export function isAuthenticMarathiWord(word: string): boolean {
    if (!word) return false;
    const clean = word.trim();
    if (FORBIDDEN_JUNK_WORDS.has(clean) || FORBIDDEN_AWKWARD_WORDS.has(clean) || isSyntheticSuffixWord(clean)) {
        return false;
    }
    return Boolean(MARATHI_DICTIONARY[clean] || USER_WORDS_SET.has(clean) || IMPORTED_VOCABULARY_2522[clean]);
}

/**
 * Checks if a word is a grammatically distorted version of a legitimate Marathi word
 * created by swapping ऱ्हस्व/दीर्घ vowels (e.g. 'वीलास' instead of 'विलास').
 * Returns the correct standard Marathi spelling if found, or null.
 */
export function getCorrectedOrthographyWord(word: string): string | null {
    if (!word || word.length < 2) return null;
    const clean = word.trim();
    if (isAuthenticMarathiWord(clean)) return null;

    // 1. Swap 'ी' -> 'ि' (e.g., 'वीलास' -> 'विलास')
    const tryShortI = clean.replace(/ी/g, 'ि');
    if (tryShortI !== clean && isAuthenticMarathiWord(tryShortI)) return tryShortI;

    // 2. Swap 'ि' -> 'ी'
    const tryLongI = clean.replace(/ि/g, 'ी');
    if (tryLongI !== clean && isAuthenticMarathiWord(tryLongI)) return tryLongI;

    // 3. Swap 'ू' -> 'ु' (e.g., 'गूलाब' -> 'गुलाब')
    const tryShortU = clean.replace(/ू/g, 'ु');
    if (tryShortU !== clean && isAuthenticMarathiWord(tryShortU)) return tryShortU;

    // 4. Swap 'ु' -> 'ू'
    const tryLongU = clean.replace(/ु/g, 'ू');
    if (tryLongU !== clean && isAuthenticMarathiWord(tryLongU)) return tryLongU;

    return null;
}

/**
 * Sanitizes a crossword clue to guarantee:
 * 1. 100% ZERO LEAKAGE: NEVER leaks or reveals the answer word inside the clue description.
 * 2. NEVER contains placeholder text like "अस्सल मराठी भाषेतील सुस्पष्ट व अर्थपूर्ण संकल्पना".
 * 3. Strips bracketed answers like [वीट] and letter count tags like (२), (४) since UI renders them dynamically.
 * 4. NEVER truncates the first letters of legitimate clue words.
 * 5. Strictly preserves user-edited clues in their full, pristine form while ensuring zero leakage.
 */
export function sanitizeClue(word: string, rawClue: string): string {
    const cleanWord = (word || '').trim();
    if (!rawClue || !rawClue.trim()) {
        if (cleanWord) {
            const dictClue = MARATHI_DICTIONARY[cleanWord] || SMART_WORD_CLUES[cleanWord];
            if (dictClue) return dictClue;
            const smartClue = generateSmartMarathiClue(cleanWord);
            if (smartClue) return smartClue;
            return 'अस्सल व सुस्पष्ट मराठी शब्दार्थ';
        }
        return '';
    }
    let cleaned = rawClue.trim();

    // 1. Remove bracketed answers and digit counts like [रग], (२)[रग], (१)[टी], (२), (३), (७)[अवसानघातकी]
    cleaned = cleaned.replace(/\([०-९0-9]+\)\s*\[.*?\]/g, ''); 
    cleaned = cleaned.replace(/\(\d+\)\s*\[.*?\]/g, ''); 
    cleaned = cleaned.replace(/\[.*?\]/g, ''); 
    cleaned = cleaned.replace(/\s*\([०-९0-9]+\)\s*$/g, '');
    cleaned = cleaned.replace(/\([०-९0-9]+\)/g, '');
    cleaned = cleaned.replace(/^[\d\u0966-\u096F]+[\.\)\-\:\s]+/g, '').trim();
    cleaned = cleaned.replace(/^[\u2022\u25AA\u25CF\u2023\u2043\*\-\_\>\»\⁃\–\—\s]+/g, '').trim();
    cleaned = cleaned.replace(/संकेतावरून ओळखा\s*/gi, '');
    cleaned = cleaned.replace(/मराठी शब्दार्थ\s*/gi, '');
    cleaned = cleaned.replace(/अस्सल मराठी शब्दार्थ\s*/gi, '');

    // 2. Remove explicit answer leaks formatted as labels or prefixes only if followed by separator:
    if (cleanWord && cleanWord.length >= 2) {
        const escapedWord = cleanWord.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        cleaned = cleaned.replace(new RegExp(`^(?:उत्तर|शब्द|उत्तरशब्द)?\\s*[:\\-–=]?\\s*['"‘“\\[\\(]?${escapedWord}['"’”\\]\\)]?\\s*[-–:;=]+\\s*`, 'i'), '');
        cleaned = cleaned.replace(new RegExp(`\\[\\s*${escapedWord}\\s*\\]`, 'gi'), '');
        cleaned = cleaned.replace(new RegExp(`\\(\\s*${escapedWord}\\s*\\)`, 'gi'), '');

        // 3. ZERO LEAKAGE ENFORCEMENT: Clean standalone whole words without damaging prefixes of other words
        cleaned = cleanClue(cleanWord, cleaned);
    }

    // 4. Remove prohibited full generic template phrases only (DO NOT strip individual words like reference or feature)
    cleaned = cleaned.replace(/वाचनात व व्यवहारात येणारा अर्थपूर्ण मराठी शब्दार्थ/gi, '');
    cleaned = cleaned.replace(/लोकसंस्कृती वा व्यवहारातील प्रचलित मूळ भाव/gi, '');
    cleaned = cleaned.replace(/['"‘“]?[^\s'"]+['"‘“’”]?\s*आद्याक्षराचा विशिष्ट भावार्थ व वाच्यार्थ/gi, '');
    cleaned = cleaned.replace(/आद्याक्षराचा विशिष्ट भावार्थ व वाच्यार्थ/gi, '');
    cleaned = cleaned.replace(/['"‘“]?[^\s'"]+['"‘“’”]?\s*अक्षरापासून सुरू होणारा/gi, '');
    cleaned = cleaned.replace(/अस्सल मराठी भाषेतील सुस्पष्ट व अर्थपूर्ण संकल्पना/gi, '');
    cleaned = cleaned.replace(/तीन अक्षरांचा अर्थपूर्ण व सुस्पष्ट देवनागरी शब्द/gi, '');
    cleaned = cleaned.replace(/दोन अक्षरांचा सुगम व प्रचलित मराठी शब्द/gi, '');
    cleaned = cleaned.replace(/चार अक्षरांचा भाषिक व सांस्कृतिक संदर्भ/gi, '');
    cleaned = cleaned.replace(/अक्षरांच्या जुळणीतून बनलेली अर्थपूर्ण मराठी संकल्पना/gi, '');
    cleaned = cleaned.replace(/लोकजीवनाशी व संस्कृतीशी जोडलेली विशिष्ट संज्ञा/gi, '');
    cleaned = cleaned.replace(/सांस्कृतिक परंपरा व साहित्यातील प्रचलित संदर्भ/gi, '');
    cleaned = cleaned.replace(/व्याकरणशुद्ध मराठी संकल्पना/gi, '');
    cleaned = cleaned.replace(/अस्सल व सुस्पष्ट मराठी शब्दार्थ/gi, '');
    cleaned = cleaned.replace(/या शब्दाचा अचूक अर्थ ओळखा/gi, '');

    // Clean surrounding stray punctuation
    cleaned = cleaned.trim().replace(/^[:;\-–=\s]+/, '').replace(/[:;\-–=\s]+$/, '').trim();

    // Guard first word and matra integrity permanently
    cleaned = guardFirstWordIntegrity(cleanWord, rawClue, cleaned);

    if (!cleaned) {
        if (cleanWord) {
            const dictClue = MARATHI_DICTIONARY[cleanWord] || SMART_WORD_CLUES[cleanWord];
            if (dictClue && !isGenericClue(dictClue)) {
                return dictClue;
            }
            return generateSmartMarathiClue(cleanWord);
        }
        return '';
    }
    return cleaned;
}


